import type { Context as ClientContext } from '@deepseek-ai/cordis'
import type { SidebarBrandMarkOwnerProps } from '@deepseek-ai/dsh-client-ui-sidebar/client'

const CLAWCLAW_ICON = 'data:image/png;base64,'

function ClawClawIcon({ size, className }: { size: number, className?: string | undefined }) {
  return <img src={CLAWCLAW_ICON} width={size} height={size} className={className} alt="" />
}

function ClawClawBrandMark({ size }: SidebarBrandMarkOwnerProps) {
  return <ClawClawIcon size={size} />
}

function ClawClawBrandName() {
  return <span style={{ fontSize: 16, fontWeight: 700, letterSpacing: '-0.03em' }}>ClawClaw</span>
}

function replaceExpandedSidebarBrand(): void {
  const button = [...document.querySelectorAll<HTMLButtonElement>('button')].find(candidate => {
    const label = candidate.getAttribute('aria-label')
    if (label !== '新建会话' && label !== 'New session') return false
    return candidate.querySelector(':scope > span[aria-hidden="true"]') !== null
  })
  const identity = button?.querySelector<HTMLSpanElement>(':scope > span[aria-hidden="true"]')
  if (identity === null || identity === undefined || identity.dataset.clawclawBrand === 'true') return
  identity.dataset.clawclawBrand = 'true'
  const mark = identity.children.item(0)
  const name = identity.children.item(1)
  if (mark !== null) {
    const icon = document.createElement('img')
    icon.src = CLAWCLAW_ICON
    icon.width = 24
    icon.height = 24
    icon.alt = ''
    mark.replaceChildren(icon)
  }
  if (name !== null) {
    const title = document.createElement('span')
    title.textContent = 'ClawClaw'
    title.style.cssText = 'font-size:16px;font-weight:700;letter-spacing:-0.03em'
    name.replaceChildren(title)
  }
}

function replaceCollapsedSidebarBrand(): void {
  const toggle = [...document.querySelectorAll<HTMLButtonElement>('button')].find(button => {
    const label = button.getAttribute('aria-label')
    return label === '打开侧边栏' || label === '收起侧边栏' || label === 'Open sidebar' || label === 'Collapse sidebar'
  })
  const mark = toggle?.querySelector<HTMLSpanElement>('span[aria-hidden="true"]')
  if (mark === null || mark === undefined || mark.dataset.clawclawBrand === 'true') return
  mark.dataset.clawclawBrand = 'true'
  const icon = document.createElement('img')
  icon.src = CLAWCLAW_ICON
  icon.width = 24
  icon.height = 24
  icon.alt = ''
  mark.replaceChildren(icon)
}

function replaceHeroCopy(root: Node = document): void {
  const replacements = new Map([
    ['探索未至之境', 'ClawClaw，万物皆有回响'],
    ['Into the Unknown', 'ClawClaw, every thought finds an answer'],
  ])
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT)
  for (let node = walker.nextNode(); node !== null; node = walker.nextNode()) {
    const text = node.textContent ?? ''
    const replacement = replacements.get(text)
    if (replacement !== undefined) node.textContent = replacement
    if (text === '预览版' || text === 'Preview') {
      const badge = node.parentElement
      if (badge !== null) badge.style.setProperty('display', 'none', 'important')
    }
  }
}

/** Apply the product identity without mutating the pinned upstream web client. */
export function applyClawClawBrand(ctx: ClientContext): void {
  if (typeof document === 'undefined') return
  document.title = 'ClawClaw'
  let favicon = document.querySelector<HTMLLinkElement>('link[rel~="icon"]')
  if (favicon === null) {
    favicon = document.createElement('link')
    favicon.rel = 'icon'
    document.head.append(favicon)
  }
  favicon.href = CLAWCLAW_ICON
  const heroStyle = document.createElement('style')
  heroStyle.textContent = '[data-slot="conversation.hero.brand.mark"] { display: none !important; }'
  document.head.append(heroStyle)

  ctx.slots.inject('sidebar.brand.mark', () => ctx.slots.register({ name: 'sidebar.brand.mark' }, ClawClawBrandMark))
  ctx.slots.inject('sidebar.brand.name', () => ctx.slots.register({ name: 'sidebar.brand.name' }, ClawClawBrandName))

  replaceHeroCopy()
  replaceExpandedSidebarBrand()
  replaceCollapsedSidebarBrand()
  const observer = new MutationObserver(records => {
    for (const record of records) replaceHeroCopy(record.target)
    replaceExpandedSidebarBrand()
    replaceCollapsedSidebarBrand()
  })
  observer.observe(document.body, { childList: true, subtree: true })
  ctx.effect(() => () => { observer.disconnect(); heroStyle.remove() }, 'dsh-plugin-desktop: ClawClaw page identity')
}
